import React, { useState, useEffect, useCallback } from 'react';
import { adminAPI, apiCall } from '../../services/apiService';
import './PendingUsers.css';

// Helper function to extract user data and break circular references
const extractUserData = (users) => {
  if (!users || !Array.isArray(users)) return [];
  
  return users.map(user => ({
    id: user.id,
    username: user.username,
    email: user.email,
    enabled: user.enabled,
    verified: user.verified,
    verificationToken: user.verificationToken,
    tokenExpiry: user.tokenExpiry,
    createdAt: user.createdAt,
    // Extract role names only, avoiding circular references
    roles: user.roles ? user.roles.map(role => ({
      id: role.id,
      name: role.name
    })) : []
  }));
};

const PendingUsers = () => {
  const [pendingUsers, setPendingUsers] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [processingUsers, setProcessingUsers] = useState(new Set());

  const fetchPendingUsers = useCallback(async () => {
    setIsLoading(true);
    setError('');

    try {
      const result = await apiCall(adminAPI.getPendingUsers);

      if (result.success) {
        let users = result.data;
        
        // Log the raw response for debugging
        console.log('Raw API response:', typeof users, users);
        
        // If the response is a string, try to parse it
        if (typeof users === 'string') {
          try {
            // Check if the string contains error messages from backend
            if (users.includes('"error":"Runtime error"') || users.includes('StackOverflowError')) {
              console.error('Backend returned error due to circular references');
              setError('Server error: Circular references detected. Please contact administrator to fix backend.');
              setPendingUsers([]);
              return;
            }
            
            // Try to clean up the JSON string first
            let cleanJsonString = users;
            
            // Find the first valid opening bracket
            const firstBracket = cleanJsonString.indexOf('[');
            if (firstBracket > 0) {
              cleanJsonString = cleanJsonString.substring(firstBracket);
            }
            
            // Remove any trailing error messages or incomplete JSON
            // Look for common patterns that indicate corrupted JSON
            const errorPatterns = [
              '{"error":',
              '{"message":',
              'Runtime error',
              'StackOverflowError',
              'Could not write JSON'
            ];
            
            for (const pattern of errorPatterns) {
              const errorIndex = cleanJsonString.indexOf(pattern);
              if (errorIndex !== -1) {
                // Find the last valid closing bracket before the error
                const beforeError = cleanJsonString.substring(0, errorIndex);
                const lastValidBracket = beforeError.lastIndexOf(']');
                if (lastValidBracket !== -1) {
                  cleanJsonString = beforeError.substring(0, lastValidBracket + 1);
                  break;
                }
              }
            }
            
            // Final cleanup - ensure it ends with a valid bracket
            const lastBracket = cleanJsonString.lastIndexOf(']');
            if (lastBracket !== -1 && lastBracket < cleanJsonString.length - 1) {
              cleanJsonString = cleanJsonString.substring(0, lastBracket + 1);
            }
            
            // Additional validation - check if string seems reasonable
            if (cleanJsonString.length < 10 || !cleanJsonString.startsWith('[')) {
              throw new Error('Invalid JSON structure detected');
            }
            
            users = JSON.parse(cleanJsonString);
            console.log('Successfully parsed JSON data after cleanup');
          } catch (parseError) {
            console.error('Failed to parse JSON:', parseError);
            console.error('JSON string length:', users.length);
            console.error('First 500 chars:', users.substring(0, 500));
            console.error('Last 500 chars:', users.substring(Math.max(0, users.length - 500)));
            
            // Check if this looks like a circular reference issue
            if (users.length > 100000 || users.includes('StackOverflowError')) {
              setError('Backend error: Circular references in data. Please contact administrator to fix the backend API.');
            } else {
              setError('Invalid data format received from server. Please try refreshing or contact support.');
            }
            setPendingUsers([]);
            return;
          }
        }
        
        // Extract clean user data, breaking circular references
        const cleanUsers = extractUserData(users);
        console.log('Extracted clean user data:', cleanUsers);
        
        setPendingUsers(cleanUsers);
      } else {
        setError(result.error);
        setPendingUsers([]);
      }
    } catch (err) {
      console.error('Error fetching pending users:', err);
      setError('Failed to fetch pending users');
      setPendingUsers([]);
    }

    setIsLoading(false);
  }, []);

  useEffect(() => {
    fetchPendingUsers();
  }, [fetchPendingUsers]);

  const handleUserVerification = async (userId, approve) => {
    setProcessingUsers(prev => new Set(prev).add(userId));

    try {
      const result = await apiCall(adminAPI.verifyUser, userId, approve);

      if (result.success) {
        setPendingUsers(prev => prev.filter(user => user.id !== userId));
        
        // Show success message
        const action = approve ? 'approved' : 'rejected';
        alert(`User has been ${action} successfully`);
      } else {
        alert(`Error: ${result.error}`);
      }
    } catch (err) {
      console.error('Error verifying user:', err);
      alert('Error: Failed to process user verification');
    }

    setProcessingUsers(prev => {
      const newSet = new Set(prev);
      newSet.delete(userId);
      return newSet;
    });
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'Unknown';
    try {
      return new Date(dateString).toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
    } catch (err) {
      return 'Invalid Date';
    }
  };

  if (isLoading) {
    return (
      <div className="loading">
        <div className="loading-spinner"></div>
        Loading pending users...
      </div>
    );
  }

  return (
    <div className="pending-users">
      <div className="page-header">
        <div className="container">
          <h1>Pending User Verifications</h1>
          <p>Review and approve new vendor registrations</p>
        </div>
      </div>

      <div className="container">
        {error && (
          <div className="alert alert-error">
            {error}
            <button onClick={fetchPendingUsers} className="btn btn-sm btn-outline">
              Retry
            </button>
          </div>
        )}

        <div className="users-summary">
          <div className="summary-card">
            <h3>{Array.isArray(pendingUsers) ? pendingUsers.length : 0}</h3>
            <p>Users awaiting verification</p>
          </div>
        </div>

        {!Array.isArray(pendingUsers) || pendingUsers.length === 0 ? (
          <div className="no-pending-users">
            <div className="no-users-icon">✓</div>
            <h3>All Caught Up!</h3>
            <p>No users are currently waiting for verification.</p>
            <button onClick={fetchPendingUsers} className="btn btn-primary">
              Refresh
            </button>
          </div>
        ) : (
          <div className="users-grid">
            {pendingUsers.map(user => (
              <UserCard
                key={user.id}
                user={user}
                onVerify={handleUserVerification}
                isProcessing={processingUsers.has(user.id)}
                formatDate={formatDate}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

const UserCard = ({ user, onVerify, isProcessing, formatDate }) => {
  const getRoleDisplayName = (roles) => {
    if (!roles || roles.length === 0) return 'No roles';
    return roles.map(role => {
      const roleName = role.name || role;
      return roleName.replace('ROLE_', '').toLowerCase();
    }).join(', ');
  };

  // Safety check for user object
  if (!user) {
    return <div className="user-card">Invalid user data</div>;
  }

  return (
    <div className="user-card">
      <div className="user-header">
        <div className="user-avatar">
          {user.username ? user.username.charAt(0).toUpperCase() : '?'}
        </div>
        <div className="user-info">
          <h3 className="user-name">{user.username || 'Unknown User'}</h3>
          <p className="user-email">{user.email || 'No email'}</p>
        </div>
      </div>

      <div className="user-details">
        <div className="detail-row">
          <span className="detail-label">Role:</span>
          <span className="detail-value">{getRoleDisplayName(user.roles)}</span>
        </div>
        <div className="detail-row">
          <span className="detail-label">Registered:</span>
          <span className="detail-value">{formatDate(user.createdAt)}</span>
        </div>
        <div className="detail-row">
          <span className="detail-label">Status:</span>
          <span className="status-badge pending">Pending Verification</span>
        </div>
      </div>

      <div className="user-actions">
        <button
          onClick={() => onVerify(user.id, false)}
          className="btn btn-danger btn-sm"
          disabled={isProcessing || !user.id}
        >
          {isProcessing ? (
            <>
              <span className="loading-spinner"></span>
              Processing...
            </>
          ) : (
            'Reject'
          )}
        </button>
        
        <button
          onClick={() => onVerify(user.id, true)}
          className="btn btn-success btn-sm"
          disabled={isProcessing || !user.id}
        >
          {isProcessing ? (
            <>
              <span className="loading-spinner"></span>
              Processing...
            </>
          ) : (
            'Approve'
          )}
        </button>
      </div>
    </div>
  );
};

export default PendingUsers;
